    def replace_in_para(para):
        """Replace placeholders in a paragraph, handling split runs."""
        text = para.text
        if not text:
            return

        # Handle conditional sections first
        # Check for IF_RELOCATION conditional
        if '{{IF_RELOCATION}}' in text or '{{END_IF_RELOCATION}}' in text:
            should_include = data.get('RELOCATION_PACKAGE', 'No') == 'Yes'

            if '{{IF_RELOCATION}}' in text and '{{END_IF_RELOCATION}}' in text:
                # Both markers in same paragraph
                if should_include:
                    # Remove just the markers, keep content
                    text = text.replace('{{IF_RELOCATION}}', '').replace('{{END_IF_RELOCATION}}', '')
                else:
                    # Remove entire content between markers (including markers)
                    text = re.sub(r'\{\{IF_RELOCATION\}\}.*?\{\{END_IF_RELOCATION\}\}', '', text, flags=re.DOTALL)
            elif '{{IF_RELOCATION}}' in text:
                if should_include:
                    text = text.replace('{{IF_RELOCATION}}', '')
                else:
                    # Mark for removal - will be handled below
                    text = text.replace('{{IF_RELOCATION}}', '{{REMOVE_START}}')
            elif '{{END_IF_RELOCATION}}' in text:
                if should_include:
                    text = text.replace('{{END_IF_RELOCATION}}', '')
                else:
                    text = text.replace('{{END_IF_RELOCATION}}', '{{REMOVE_END}}')

