        for match in re.finditer(pattern, text):
            key = match.group(1)
            placeholder = match.group(0)
            if key in data:
                text = text.replace(placeholder, str(data[key]))
        return text

    def process_para(para):
        """Process a single paragraph - replace placeholders and handle conditionals."""
        text = para.text
        if not text:
            return

        # Handle IF_RELOCATION markers
        text = text.replace('{{IF_RELOCATION}}', '')
        text = text.replace('{{END_IF_RELOCATION}}', '')

        # Replace all data placeholders
        text = replace_placeholders_in_text(text)

        # Apply changes to paragraph - preserve first run's formatting
        if para.runs:
            para.runs[0].text = text
            for run in para.runs[1:]:
                run.text = ''

    def should_remove_para(para_text):
        """Check if paragraph should be removed (in non-relocation conditional)."""
        # This will be tracked by the caller
        return False

    def process_paragraphs(paragraphs):
        """Process paragraphs with conditional section handling."""
        in_conditional = False

        for para in paragraphs:
            text = para.text

            # Check for start of conditional
            if '{{IF_RELOCATION}}' in text:
                in_conditional = True
                if not include_relocation:
                    # Clear this paragraph if we're not including relocation
                    if para.runs:
                        para.runs[0].text = ''
                        for run in para.runs[1:]:
                            run.text = ''
                    if '{{END_IF_RELOCATION}}' in text:
