                else:
                    text = text.replace('{{END_IF_RELOCATION}}', '{{REMOVE_END}}')

        # Replace all data placeholders
        pattern = r'\{\{([A-Z_]+)\}\}'
        for match in re.finditer(pattern, text):
            key = match.group(1)
            placeholder = match.group(0)
            if key in data:
                text = text.replace(placeholder, str(data[key]))

        # Apply changes to paragraph
        if para.runs:
            para.runs[0].text = text
            for run in para.runs[1:]:
                run.text = ''

    def process_paragraphs(paragraphs):
        """Process a list of paragraphs, handling multi-paragraph conditionals."""
        in_removal = False
        for para in paragraphs:
            text = para.text

            # Check if we should start removal
            if '{{IF_RELOCATION}}' in text and data.get('RELOCATION_PACKAGE', 'No') != 'Yes':
                in_removal = True

            # Check if conditional markers span paragraphs when we should keep content
            if '{{IF_RELOCATION}}' in text and data.get('RELOCATION_PACKAGE', 'No') == 'Yes':
                # Just remove the marker
                if para.runs:
                    para.runs[0].text = text.replace('{{IF_RELOCATION}}', '')
                    for run in para.runs[1:]:
                        run.text = ''
                continue

            if '{{END_IF_RELOCATION}}' in text and data.get('RELOCATION_PACKAGE', 'No') == 'Yes':
                # Just remove the marker
                if para.runs:
                    para.runs[0].text = text.replace('{{END_IF_RELOCATION}}', '')
                    for run in para.runs[1:]:
                        run.text = ''
                in_removal = False
                continue

            if in_removal:
                # Clear this paragraph
                if para.runs:
                    para.runs[0].text = ''
                    for run in para.runs[1:]:
                        run.text = ''
                if '{{END_IF_RELOCATION}}' in text:
                    in_removal = False
                continue

            # Normal replacement
            replace_in_para(para)

    # Process main document paragraphs
    process_paragraphs(doc.paragraphs)

    # Process tables (with nesting)
    def process_table(table):
        for row in table.rows:
            for cell in row.cells:
                process_paragraphs(cell.paragraphs)
                for nested in cell.tables:
                    process_table(nested)

    for table in doc.tables:
        process_table(table)

    # Process headers/footers
    for section in doc.sections:
        process_paragraphs(section.header.paragraphs)
        process_paragraphs(section.footer.paragraphs)
        # Also check for tables in headers/footers
        for table in section.header.tables:
            process_table(table)
        for table in section.footer.tables:
            process_table(table)

    doc.save(output_path)
    print(f"Offer letter saved to {output_path}")

